import express from 'express';
const app = express();

app.get('/users', (req, res) => {
  const users = [{ id: 1, name: 'John' }];
  res.json(users); // Express otomatis menangani content negotiation untuk JSON
});

// Untuk XML, gunakan middleware atau res.format
app.get('/users', (req, res) => {
  res.format({
    'application/json': () => res.json([{ id: 1, name: 'John' }]),
    'application/xml': () => res.xml('<users><user id="1">John</user></users>')
  });
});

app.listen(3000);
